"""Seal the already completed TestPilot course without executing another test."""
from __future__ import annotations
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def identity(body):
    return {"bytes": len(body), "sha256": hashlib.sha256(body).hexdigest(),
            "git_blob": hashlib.sha1(b"blob " + str(len(body)).encode("ascii") + b"\0" + body).hexdigest()}


def verified_text(relative):
    path = ROOT / relative
    if path.is_symlink() or not path.is_file() or path.stat().st_uid != os.getuid():
        raise RuntimeError("not an owned regular evidence file: " + relative)
    body = path.read_bytes()
    return {"path": relative, **identity(body), "encoding": "utf-8", "content": body.decode("utf-8")}


def write_new(relative, data):
    body = (json.dumps(data, indent=2, ensure_ascii=False) + "\n").encode("utf-8")
    with (ROOT / relative).open("xb") as stream:
        stream.write(body)
    return identity(body)


